import sys,json
from collections import OrderedDict
class LRUCache:
    def __init__(self,capacity): self.capacity=capacity; self.cache=OrderedDict()
    def get(self,key):
        if key not in self.cache: return -1
        v=self.cache.pop(key); self.cache[key]=v; return v
    def put(self,key,value):
        if key in self.cache: self.cache.pop(key)
        self.cache[key]=value
        if len(self.cache)>self.capacity: self.cache.popitem(last=False)
def run(ops,args):
    o=None;r=[]
    for op,a in zip(ops,args):
        if op=="LRUCache": o=LRUCache(a[0]);r.append(None)
        elif op=="get": r.append(o.get(a[0]))
        else: o.put(a[0],a[1]);r.append(None)
    return r
ops,args=json.loads(sys.stdin.readline());print(json.dumps(run(ops,args),separators=(",",":")))

